import { useState, useEffect, useRef } from 'react';
const SUGGESTIONS = ['Nature','Technology','Travel','Architecture','People','Food','Space','Art','Business','Fashion'];

export function ImageSearch() {
  const [query, setQuery] = useState('');
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [selected, setSelected] = useState(null);
  const [error, setError] = useState('');
  const loadingRef = useRef(false);
  const sentinelRef = useRef(null);
  const currentQueryRef = useRef('');

  const search = async (q, pg) => {
    const qq = q !== undefined ? q : query;
    const p = pg !== undefined ? pg : 1;
    if (!qq.trim()) return;
    if (loadingRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    setError('');
    try {
      const { data } = await axios.get('https://api.pexels.com/v1/search', {
        headers: { Authorization: PEXELS_KEY },
        params: { query: qq, per_page: 15, page: p },
      });
      if (p === 1) {
        setImages(data.photos);
      } else {
        setImages(prev => [...prev, ...data.photos]);
      }
      setTotal(data.total_results);
      setPage(p);
    } catch (err) {
      setError('Failed to load images. Try again.');
    } finally {
      setLoading(false);
      loadingRef.current = false;
    }
  };

  const handleNewSearch = (q) => {
    currentQueryRef.current = q;
    setImages([]);
    setPage(1);
    setTotal(0);
    search(q, 1);
  };

  useEffect(() => {
    if (!sentinelRef.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (
          entry.isIntersecting &&
          !loadingRef.current &&
          images.length > 0 &&
          images.length < total
        ) {
          search(currentQueryRef.current, page + 1);
        }
      },
      { rootMargin: '400px' }
    );
    observer.observe(sentinelRef.current);
    return () => observer.disconnect();
  }, [images.length, total, page]);

  return (
    <div style={{ background: '#fff', minHeight: '100vh' }}>
      <style>{imageSearchCSS}</style>

      <div style={is.header}>
        <div className="container">
          <h1 style={is.title}>Inkwell Images</h1>
          <p style={is.sub}>Discover, search, and save high-quality visuals effortlessly</p>
          <div style={is.searchBar}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#9b9b9b" strokeWidth="2">
              <circle cx="11" cy="11" r="8"/>
              <path d="m21 21-4.35-4.35"/>
            </svg>
            <input
              style={is.searchInput}
              placeholder="Search for photos..."
              value={query}
              onChange={e => setQuery(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') {
                  handleNewSearch(query);
                }
              }}
            />
            <button style={is.searchBtn} onClick={() => handleNewSearch(query)}>Search</button>
          </div>
          <div style={is.chips}>
            {SUGGESTIONS.map(s => (
              <button
                key={s}
                style={is.chip}
                onClick={() => {
                  setQuery(s);
                  setTimeout(() => handleNewSearch(s), 50);
                }}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="container" style={{ paddingBottom: 60 }}>
        {error && <div style={is.error}>{error}</div>}

        {!loading && images.length === 0 && (
          <div style={is.empty}>
            <div style={{ fontSize: 64, marginBottom: 16 }}>🔍</div>
            <h3 style={{ fontFamily: 'Lora, serif', fontSize: 22, marginBottom: 8 }}>Explore beautiful photos</h3>
            <p style={{ color: '#9b9b9b', fontSize: 15 }}>Search for any topic above to get started.</p>
          </div>
        )}

        {images.length > 0 && (
          <div>
            <div style={{ fontSize: 13, color: '#9b9b9b', margin: '24px 0 16px' }}>
              {total.toLocaleString()} results for &quot;{currentQueryRef.current}&quot;
            </div>

            <div style={is.masonryGrid} className="masonry-grid">
              {images.map((img, idx) => (
                <PinCard key={img.id + '-' + idx} img={img} onSelect={setSelected} />
              ))}
              {loading && Array.from({ length: 6 }).map((_, i) => (
                <div key={'sk' + i} className="pin-skeleton" />
              ))}
            </div>

            {/* Invisible sentinel for infinite scroll */}
            <div ref={sentinelRef} style={{ height: 1 }} />

            {/* Load more hidden but kept for fallback */}
            <div style={{ textAlign: 'center', marginTop: 20, visibility: 'hidden', height: 0, overflow: 'hidden' }}>
              <button style={is.loadMore} onClick={() => search(currentQueryRef.current, page + 1)} disabled={loading}>
                {loading ? 'Loading...' : 'Load more'}
              </button>
            </div>

            {loading && images.length > 0 && (
              <div style={{ textAlign: 'center', padding: '24px 0' }}>
                <div className="pin-spinner" />
              </div>
            )}

            {!loading && images.length >= total && total > 0 && (
              <div style={{ textAlign: 'center', padding: '32px 0', fontSize: 13, color: '#9b9b9b' }}>
                All {total.toLocaleString()} images loaded
              </div>
            )}
          </div>
        )}
      </div>

      {selected && (
        <div style={is.lightbox} onClick={() => setSelected(null)}>
          <div style={is.lightboxBox} onClick={e => e.stopPropagation()}>
            <button style={is.closeBtn} onClick={() => setSelected(null)}>✕</button>
            <img src={selected.src.large} alt={selected.alt} style={is.lightboxImg} />
            <div style={is.lightboxFooter}>
              <div>
                <div style={{ fontWeight: 600, fontSize: 15, marginBottom: 4 }}>{selected.alt || 'Photo'}</div>
                <div style={{ fontSize: 13, color: '#9b9b9b' }}>by <strong>{selected.photographer}</strong> on Pexels</div>
              </div>
              <div style={{ display: 'flex', gap: 10 }}>
                <a href={selected.url} target="_blank" rel="noreferrer" style={is.viewBtn}>View on Pexels</a>
                <a href={selected.src.original} download target="_blank" rel="noreferrer" style={is.dlBtn2}>↓ Original</a>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function handleDownload(url, e) {
  e.stopPropagation();
  e.preventDefault();
  fetch(url)
    .then(res => res.blob())
    .then(blob => {
      const blobUrl = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = 'inkwell-image.jpg';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(blobUrl);
    })
    .catch(() => {
      window.open(url, '_blank');
    });
}

function PinCard({ img, onSelect }) {
  const ratio = img.height / img.width;
  const pt = (ratio * 100).toFixed(2) + '%';
  const [loaded, setLoaded] = useState(false);

  return (
    <div
      style={is.card}
      className="pin-card"
      onClick={() => onSelect(img)}
    >
      <div style={{ position: 'relative', width: '100%', paddingTop: pt }}>
        {!loaded && <div className="pin-skeleton-inner" />}
        <img
          src={img.src.medium}
          alt={img.alt}
          onLoad={() => setLoaded(true)}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            display: 'block',
            borderRadius: 16,
            opacity: loaded ? 1 : 0,
            transition: 'opacity 0.5s ease, transform 0.35s ease, filter 0.35s ease',
            transform: 'scale(1)',
            filter: 'brightness(1)',
          }}
          className="pin-img"
        />
        <div
          className="pin-overlay"
          style={{
            position: 'absolute',
            inset: 0,
            background: 'linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.2) 50%, transparent 100%)',
            opacity: 0,
            transition: 'opacity 0.25s ease',
            display: 'flex',
            alignItems: 'flex-end',
            padding: '14px 12px',
            borderRadius: 16,
            pointerEvents: 'none',
          }}
        >
          <span style={{
            fontSize: 12,
            color: '#fff',
            fontWeight: 600,
            letterSpacing: '0.01em',
            textShadow: '0 1px 3px rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            gap: 5,
          }}>
            <span style={{ fontSize: 11 }}>📷</span>
            {img.photographer}
          </span>
        </div>
        <button
          className="pin-dlbtn"
          onClick={e => handleDownload(img.src.original, e)}
          title="Download"
          style={{
            position: 'absolute',
            top: 10,
            right: 10,
            width: 40,
            height: 40,
            borderRadius: '50%',
            background: '#e30d10',
            color: '#fff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: 'none',
            cursor: 'pointer',
            zIndex: 10,
            boxShadow: '0 2px 12px rgba(0,0,0,0.35)',
            fontSize: 17,
            fontWeight: 700,
            lineHeight: 1,
            transition: 'opacity 0.2s ease, transform 0.15s ease, background 0.15s ease',
          }}
        >
          ↓
        </button>
      </div>
    </div>
  );
}

const imageSearchCSS = `
  /* Masonry grid */
  .masonry-grid {
    columns: 4 220px;
    column-gap: 12px;
    margin-top: 8px;
    width: 100%;
    box-sizing: border-box;
    overflow-x: hidden;
  }

  /* Pin card base */
  .pin-card {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    box-sizing: border-box;
    border-radius: 16px;
    overflow: hidden;
    cursor: pointer;
    background: #f0f0f0;
    position: relative;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    will-change: transform;
  }

  /* Card hover lift */
  .pin-card:hover {
    transform: translateY(-4px) scale(1.01);
    box-shadow: 0 12px 32px rgba(0,0,0,0.18);
  }

  /* Image zoom + brightness on hover */
  .pin-card:hover .pin-img {
    transform: scale(1.07) !important;
    filter: brightness(1.06) !important;
  }

  /* Overlay fade in on hover */
  .pin-card:hover .pin-overlay {
    opacity: 1 !important;
  }

  /* Download button: hidden on desktop, shown on hover */
  .pin-dlbtn {
    opacity: 0;
  }
  .pin-card:hover .pin-dlbtn {
    opacity: 1;
  }
  .pin-dlbtn:hover {
    transform: scale(1.12) !important;
    background: #c00a0d !important;
  }
  .pin-dlbtn:active {
    transform: scale(0.93) !important;
  }

  /* Skeleton shimmer */
  .pin-skeleton {
    break-inside: avoid;
    margin-bottom: 12px;
    display: block;
    width: 100%;
    height: 240px;
    border-radius: 16px;
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: shimmer 1.4s infinite;
    box-sizing: border-box;
  }

  .pin-skeleton-inner {
    position: absolute;
    inset: 0;
    border-radius: 16px;
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    animation: shimmer 1.4s infinite;
  }

  @keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }

  /* Spinner for infinite scroll loading */
  .pin-spinner {
    width: 32px;
    height: 32px;
    border: 3px solid #f0f0f0;
    border-top-color: #e30d10;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
    margin: 0 auto;
  }

  @keyframes spin {
    to { transform: rotate(360deg); }
  }

  /* Responsive masonry */
  @media (max-width: 1024px) {
    .masonry-grid { columns: 3 180px !important; }
  }
  @media (max-width: 768px) {
    .masonry-grid { columns: 2 140px !important; column-gap: 10px !important; }
    .pin-card { margin-bottom: 10px !important; }
    .pin-card:hover {
      transform: none !important;
      box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important;
    }
    .pin-card:hover .pin-img {
      transform: scale(1) !important;
      filter: brightness(1) !important;
    }
    .pin-dlbtn {
      opacity: 1 !important;
      width: 34px !important;
      height: 34px !important;
      top: 8px !important;
      right: 8px !important;
      font-size: 15px !important;
    }
    .pin-overlay { opacity: 1 !important; }
  }
  @media (max-width: 480px) {
    .masonry-grid { columns: 2 110px !important; column-gap: 8px !important; }
    .pin-card { margin-bottom: 8px !important; border-radius: 10px !important; }
    .pin-skeleton { height: 160px !important; border-radius: 10px !important; }
  }

  .pin-card:active { opacity: 0.94; }
`;

